import { BrandMark } from '@/components/ui';
import { QR_PLATE } from './qr.constants';
import type { QrPlateMarkProps } from './qr.types';

/**
 * The Seti mark, in the middle of the code, in the well the geometry cleared for it.
 *
 * `neutral`, not `friendly`: a code is a document — it is the thing a stranger scans
 * and a printer prints — and the kit's role map puts documents on the neutral face.
 *
 * `canvas="code"` is the kit's cobalt colourway, generated by
 * `design-kit/seti.live/marks/generate.py`. It is not a recolour of another file: the
 * cream mark is 1.3:1 on this white well and reads as two eyes with no head, and the
 * white mark is 1:1. Cobalt is the same ink as the modules (6.06:1 on white), which is
 * what makes the code read as one object.
 *
 * It is a raster laid over the vector rather than an `<image>` inside it, because a
 * serialised SVG loaded as an image will not fetch an external href. The export draws
 * the same mark at the same place — see `useDownloadQr`.
 */
export function QrPlateMark({ width }: QrPlateMarkProps) {
  return (
    <span aria-hidden="true" className={QR_PLATE.mark} style={{ width }}>
      <BrandMark expression="neutral" canvas="code" className="h-full w-auto" />
    </span>
  );
}
